// Monta o payload em base64 para o Execute Command.
//
// Isto vive num nó de CÓDIGO, não numa expressão, por um motivo aprendido na
// prática em 15/09/2026: expressões do n8n NÃO têm `Buffer`. A expressão
// resolvia para vazio, o script era chamado sem argumento nenhum e devolvia
// "parametros_invalidos" — a execução aparecia como sucesso e nada acontecia,
// que é o pior tipo de falha: silenciosa.
//
// Base64 também evita o problema de escape: o evento da Evolution tem ~14 KB
// de JSON com aspas e acentos, e interpolar isso cru num comando de shell
// quebraria.
const body = $input.first().json.body || $input.first().json;
return [{ json: { payloadB64: Buffer.from(JSON.stringify(body)).toString('base64') } }];

// processar-mensagem.js imprime UM json em stdout com o resultado do fluxo
// inteiro (interpretação, OCR, consulta e, se for o caso, validação) e já
// enviou a resposta ao grupo via --enviar.
//
// O n8n aqui é só um cano: não decide nada, apenas lê o resultado para o log
// e para a notificação de admin. Toda a lógica vive em código versionado —
// nós de código do n8n não conseguem importar os arquivos do projeto, e
// duplicar lógica aqui foi o que já deixou produção fora de sincronia antes.
const stdout = $input.item.json.stdout || '';
const linhas = stdout.trim().split('\n').filter(Boolean);
const ultimaLinha = linhas[linhas.length - 1];

if (!ultimaLinha) {
  return { json: { status: 'erro', mensagem: 'processar-mensagem.js não retornou nada em stdout.', notificarAdmin: true } };
}

try {
  return { json: JSON.parse(ultimaLinha) };
} catch (err) {
  return { json: { status: 'erro', mensagem: `Saída não-json: ${ultimaLinha.slice(0, 300)}`, notificarAdmin: true } };
}
